class Tracer:
    def __enter__(self):
        print("进入")
        return self

    def __exit__(self, exc_type, exc, tb):
        print("退出，异常类型：", exc_type.__name__ if exc_type else "无")
        return False


with Tracer() as t:
    print("干活中")

class Guard:
    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, tb):
        print("清理（异常也走这里）")
        return False


try:
    with Guard():
        raise ValueError("炸了")
except ValueError as exc:
    print("外面捕获：", exc)
